    $orders->save($order);

    $this->client->submitForm('Potvrdit objednávku');
    $this->client->followRedirect();
    $this->client->submitForm('Zaplatit');
    $this->client->followRedirect();
    self::assertSame(8, $stockItems->get($keyboard)->available());

    $this->client->submitForm('Stornovat objednávku');
    $this->client->followRedirect();

    self::assertSelectorTextContains('strong', 'cancelled');
    $order = $this->orderFromUrl();
    self::assertSame(OrderStatus::Cancelled, $order->status);
    self::assertTrue($order->refunded->equals(new Money(900_00, Currency::CZK)));
    self::assertSame(10, $stockItems->get($keyboard)->available());
    self::assertSelectorNotExists('form[action$="/stornovat"]');
}

